    assert failed.isCompletedExceptionally();
  }
}

public class Main {
  static final class Account {
    private int balance = 100;
    synchronized boolean withdraw(int amount) {
      if (amount <= 0) throw new IllegalArgumentException("amount");
      if (balance < amount) return false;
      balance -= amount;
      return true;
    }
    synchronized int balance() { return balance; }
  }
  public static void main(String[] args) throws InterruptedException {
    Account account = new Account();
    Thread first = new Thread(() -> account.withdraw(80));
    Thread second = new Thread(() -> account.withdraw(80));
    first.start();
    second.start();
    first.join();
    second.join();
    assert account.balance() == 20;
  }
}

import java.util.concurrent.atomic.AtomicInteger;

public class Main {
  public static void main(String[] args) throws InterruptedException {
    AtomicInteger count = new AtomicInteger();
    Runnable work = () -> {
      for (int i = 0; i < 1000; i++) count.incrementAndGet();
    };
    Thread first = new Thread(work);
    Thread second = new Thread(work);
    first.start(); second.start();
    first.join(); second.join();
    assert count.get() == 2000;
    boolean changed = count.compareAndSet(2000, 0);
    assert changed && count.get() == 0;
  }
}

import java.util.concurrent.ConcurrentHashMap;

public class Main {
  public static void main(String[] args) throws InterruptedException {
    var counts = new ConcurrentHashMap<String, Integer>();
    Runnable work = () -> {
      for (int i = 0; i < 1000; i++) counts.merge("paid", 1, Integer::sum);
    };
    Thread first = new Thread(work);
    Thread second = new Thread(work);
    first.start(); second.start();
    first.join(); second.join();
    assert counts.get("paid") == 2000;
    assert counts.get("missing") == null;
  }
}
